// ============================================================================
// PQ_MEMC_apb: APB4 register wrapper around PQ_MEMC_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/PQ_MEMC.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/PQ_MEMC.md
// ============================================================================
module PQ_MEMC_apb #(
  parameter logic [3:0] AXI_ID = 4'd8,
  parameter int MAXW = 64
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C080100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [20:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd21) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_cur_addr;
  logic [31:0]   c_prev_addr;
  logic [31:0]   c_dst_addr;
  logic [15:0]   c_stride;
  logic [15:0]   c_h_active;
  logic [15:0]   c_v_active;
  logic          c_memc_en;
  logic [7:0]    c_mv_frac;
  logic          c_tone_en;
  logic [31:0]   c_meta0;
  logic [31:0]   c_meta1;
  logic [31:0]   c_meta2;
  logic [31:0]   c_meta3;
  logic [15:0]   c_display_peak;
  logic          c_meta_load;
  logic          c_start;
  logic          c_busy;
  logic          c_err;
  logic          c_cfg_err;
  logic          c_params_ok;
  logic [15:0]   c_tone_slope;
  logic [15:0]   c_content_max;
  logic [15:0]   c_lines;
  logic [31:0]   c_cycles;
  logic          c_done;
  logic          c_err_irq;
  PQ_MEMC_top #(.AXI_ID(AXI_ID), .MAXW(MAXW)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .cur_addr(c_cur_addr),
    .prev_addr(c_prev_addr),
    .dst_addr(c_dst_addr),
    .stride(c_stride),
    .h_active(c_h_active),
    .v_active(c_v_active),
    .memc_en(c_memc_en),
    .mv_frac(c_mv_frac),
    .tone_en(c_tone_en),
    .meta0(c_meta0),
    .meta1(c_meta1),
    .meta2(c_meta2),
    .meta3(c_meta3),
    .display_peak(c_display_peak),
    .meta_load(c_meta_load),
    .start(c_start),
    .busy(c_busy),
    .err(c_err),
    .cfg_err(c_cfg_err),
    .params_ok(c_params_ok),
    .tone_slope(c_tone_slope),
    .content_max(c_content_max),
    .lines(c_lines),
    .cycles(c_cycles),
    .done(c_done),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_CUR_ADDR;   // 12'h014 CUR_ADDR
  logic [31:0] r_PREV_ADDR;   // 12'h018 PREV_ADDR
  logic [31:0] r_DST_ADDR;   // 12'h01C DST_ADDR
  logic [31:0] r_GEOM;   // 12'h020 GEOM
  logic [15:0] r_V_ACTIVE;   // 12'h024 V_ACTIVE
  logic [9:0] r_CTRL;   // 12'h028 CTRL
  logic [31:0] r_META0;   // 12'h02C META0
  logic [31:0] r_META1;   // 12'h030 META1
  logic [31:0] r_META2;   // 12'h034 META2
  logic [31:0] r_META3;   // 12'h038 META3
  logic [15:0] r_DISPLAY_PEAK;   // 12'h03C DISPLAY_PEAK
  logic [1:0] p_CMD;   // 12'h040 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CUR_ADDR <= 32'h0;
      r_PREV_ADDR <= 32'h0;
      r_DST_ADDR <= 32'h0;
      r_GEOM <= 32'h0;
      r_V_ACTIVE <= 16'h0;
      r_CTRL <= 10'h0;
      r_META0 <= 32'h0;
      r_META1 <= 32'h0;
      r_META2 <= 32'h0;
      r_META3 <= 32'h0;
      r_DISPLAY_PEAK <= 16'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CUR_ADDR <= (r_CUR_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_PREV_ADDR <= (r_PREV_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_DST_ADDR <= (r_DST_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_GEOM <= (r_GEOM & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_V_ACTIVE <= (r_V_ACTIVE & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[10]) r_CTRL <= (r_CTRL & ~wmask[9:0]) | (PWDATA[9:0] & wmask[9:0]);
      if (wr && hit[11]) r_META0 <= (r_META0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_META1 <= (r_META1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_META2 <= (r_META2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_META3 <= (r_META3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_DISPLAY_PEAK <= (r_DISPLAY_PEAK & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[16]) ? PWDATA[1:0] & wmask[1:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cur_addr = r_CUR_ADDR[31:0];
  assign c_prev_addr = r_PREV_ADDR[31:0];
  assign c_dst_addr = r_DST_ADDR[31:0];
  assign c_stride = r_GEOM[15:0];
  assign c_h_active = r_GEOM[31:16];
  assign c_v_active = r_V_ACTIVE[15:0];
  assign c_memc_en = r_CTRL[0:0];
  assign c_mv_frac = r_CTRL[8:1];
  assign c_tone_en = r_CTRL[9:9];
  assign c_meta0 = r_META0[31:0];
  assign c_meta1 = r_META1[31:0];
  assign c_meta2 = r_META2[31:0];
  assign c_meta3 = r_META3[31:0];
  assign c_display_peak = r_DISPLAY_PEAK[15:0];
  assign c_meta_load = p_CMD[0:0];
  assign c_start = p_CMD[1:1];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CUR_ADDR);
      10'd6: apb_rdata = 32'(r_PREV_ADDR);
      10'd7: apb_rdata = 32'(r_DST_ADDR);
      10'd8: apb_rdata = 32'(r_GEOM);
      10'd9: apb_rdata = 32'(r_V_ACTIVE);
      10'd10: apb_rdata = 32'(r_CTRL);
      10'd11: apb_rdata = 32'(r_META0);
      10'd12: apb_rdata = 32'(r_META1);
      10'd13: apb_rdata = 32'(r_META2);
      10'd14: apb_rdata = 32'(r_META3);
      10'd15: apb_rdata = 32'(r_DISPLAY_PEAK);
      10'd17: apb_rdata = 32'({c_params_ok, c_cfg_err, c_err, c_busy});
      10'd18: apb_rdata = 32'({c_content_max, c_tone_slope});
      10'd19: apb_rdata = 32'({c_lines});
      10'd20: apb_rdata = 32'({c_cycles});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
